import{_ as a,o as i,c as e,a2 as t}from"./chunks/framework.DDEX3mHW.js";const c=JSON.parse('{"title":"升级","description":"","frontmatter":{},"headers":[],"relativePath":"guide/upgrade.md","filePath":"guide/upgrade.md","lastUpdated":1792059802000}'),l={name:"guide/upgrade.md"};function h(n,s,p,r,o,d){return i(),e("div",null,[...s[0]||(s[0]=[t('<h1 id="升级" tabindex="-1">升级 <a class="header-anchor" href="#升级" aria-label="Permalink to &quot;升级&quot;">​</a></h1><h2 id="面板内升级" tabindex="-1">面板内升级 <a class="header-anchor" href="#面板内升级" aria-label="Permalink to &quot;面板内升级&quot;">​</a></h2><p><strong>网站配置</strong> → <strong>面板自升级</strong> → <strong>检查更新</strong> → <strong>立即升级</strong>。</p><p>升级会拉取新镜像并重建前后端容器，约 1 分钟后刷新页面即可。页面没有变化时，通常是浏览器或 CDN 缓存，刷新或清理缓存即可。</p><h2 id="脚本升级" tabindex="-1">脚本升级 <a class="header-anchor" href="#脚本升级" aria-label="Permalink to &quot;脚本升级&quot;">​</a></h2><p>在面板部署目录（存放 <code>docker-compose.yml</code> 和 <code>.env</code> 的目录）重新运行安装脚本，选 <code>2. 更新面板</code>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -L</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/kure29/flvx/releases/latest/download/panel_install.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> panel_install.sh</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +x</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> panel_install.sh</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./panel_install.sh</span></span></code></pre></div><p>数据会保留，更新前会自动备份到部署目录的 <code>backups/</code>。</p><h2 id="指定版本" tabindex="-1">指定版本 <a class="header-anchor" href="#指定版本" aria-label="Permalink to &quot;指定版本&quot;">​</a></h2><p>到 <a href="https://github.com/kure29/flvx/releases" target="_blank" rel="noreferrer">Releases</a> 复制对应版本的命令，例如：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -L</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/kure29/flvx/releases/download/3.0.7/panel_install.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> panel_install.sh</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +x</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> panel_install.sh</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./panel_install.sh</span></span></code></pre></div><h2 id="节点-agent-升级" tabindex="-1">节点 agent 升级 <a class="header-anchor" href="#节点-agent-升级" aria-label="Permalink to &quot;节点 agent 升级&quot;">​</a></h2><p><strong>节点</strong> 页选择节点 → <strong>升级</strong>，留空版本即使用最新版。也可以在节点上重新运行节点安装脚本。</p><h2 id="修复面板内升级" tabindex="-1">修复面板内升级 <a class="header-anchor" href="#修复面板内升级" aria-label="Permalink to &quot;修复面板内升级&quot;">​</a></h2><p>面板内升级提示“部署docker-compose.yml不可用”时：3.0.6 及更早版本的面板内升级会把后端容器的部署目录挂载弄丢，之后面板内升级会一直提示这个错误。数据不受影响，修复一次即可：</p><ol><li><p>在服务器上进入存放 <code>docker-compose.yml</code> 和 <code>.env</code> 的目录（常见为 <code>/root</code>，或当初运行安装脚本的目录），用 <code>ls</code> 确认这两个文件都在</p></li><li><p>执行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --force-recreate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backend</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> frontend</span></span></code></pre></div></li></ol><p>也可以在该目录运行 3.0.7 及以后的安装脚本，选“更新面板”，会顺带修复。</p>',17)])])}const g=a(l,[["render",h]]);export{c as __pageData,g as default};
